import { ArtemisButton } from "../../../foundations/button";
import { CATEGORY_TABS, type CategoryFilter, type Day, dayKey, INITIAL_DATE, INITIAL_EVENTS, MONTHS_SHORT, makeDay, matchesQuery, monthLabel, monthTitle, type PlannerEvent, type PlannerView, parseDay, periodKey, todayKey, weekLabel, weekTitle, } from "./02-planner/data";
import { AddEventDialog, EventDetailsDialog, type NewEventInput } from "./02-planner/dialogs";
import { PlannerField } from "./02-planner/field";
import { PLANNER_INDICATOR_SPRING, PlannerSegmentedTabs } from "./02-planner/segmented";
import { MonthView, WeekView } from "./02-planner/views";
const VIEW_TABS: ReadonlyArray<{
    value: PlannerView;
    label: string;
}> = [
    { value: "month", label: "Month" },
    { value: "week", label: "Week" },
];
const NAV_BUTTON = "art:size-9 art:h-9";
const TODAY_BUTTON = "art:inline-block art:p-0 art:text-inherit art:hover:bg-transparent art:hover:text-inherit art:h-8 art:min-w-16 art:px-3 art:font-medium art:text-xs art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring";
export default function CalendarPlanner() {
const artemisInstanceId = useArtemisInstanceId();

    const underlineId = useId();
    const reduce = useReducedMotion();
    const [today] = useState(todayKey);
    const [view, setView] = useState<PlannerView>("month");
    const [selected, setSelected] = useState(INITIAL_DATE);
    const [direction, setDirection] = useState(1);
    const [category, setCategory] = useState<CategoryFilter>("all");
    const [query, setQuery] = useState("");
    const [events, setEvents] = useState<PlannerEvent[]>(() => [...INITIAL_EVENTS]);
    const [nextId, setNextId] = useState(INITIAL_EVENTS.length + 1);
    const [detailsEvent, setDetailsEvent] = useState<PlannerEvent | null>(null);
    const [detailsOpen, setDetailsOpen] = useState(false);
    const [confirming, setConfirming] = useState(false);
    const [addOpen, setAddOpen] = useState(false);
    const [addDate, setAddDate] = useState(INITIAL_DATE);
    const [addKey, setAddKey] = useState(0);
    const anchor = parseDay(selected);
    const term = query.trim().toLowerCase();
    const visible = useMemo(() => events.filter((event) => (category === "all" || event.category === category) && matchesQuery(event, term)), [events, category, term]);
    const eventsByDate = useMemo(() => {
        const map = new Map<string, PlannerEvent[]>();
        for (const event of visible) {
            const list = map.get(event.date);
            if (list)
                list.push(event);
            else
                map.set(event.date, [event]);
        }
        return map;
    }, [visible]);
    const goTo = (next: Day, nextView: PlannerView = view) => {
        const from = periodKey(nextView, anchor);
        const to = periodKey(nextView, next);
        if (to !== from)
            setDirection(to > from ? 1 : -1);
        setSelected(dayKey(next));
    };
    const step = (delta: number) => {
        if (view === "month")
            goTo(makeDay(anchor.y, anchor.m + delta, 1));
        else
            goTo(makeDay(anchor.y, anchor.m, anchor.d + delta * 7));
    };
    const viewingToday = periodKey(view, anchor) === periodKey(view, parseDay(today));
    const periodLabel = viewingToday ? "Today" : view === "month" ? monthLabel(anchor) : weekLabel(anchor);
    const unit = view === "month" ? "month" : "week";
    const openAdd = (date: string) => {
        setAddDate(date);
        setAddKey((k) => k + 1);
        setAddOpen(true);
    };
    const openEvent = (event: PlannerEvent) => {
        setDetailsEvent(event);
        setConfirming(false);
        setDetailsOpen(true);
    };
    const createEvent = (input: NewEventInput) => {
        const event: PlannerEvent = {
            id: `event-${nextId}`,
            title: input.title,
            category: "meetings",
            tone: "primary",
            date: input.date,
            start: input.start,
            end: input.end,
        };
        setNextId((n) => n + 1);
        setEvents((prev) => [...prev, event]);
        setAddOpen(false);
        goTo(parseDay(input.date));
    };
    const deleteEvent = (event: PlannerEvent) => {
        setEvents((prev) => prev.filter((e) => e.id !== event.id));
        setDetailsOpen(false);
    };
    const showDay = (key: string) => {
        setSelected(key);
        setView("week");
    };
    return (<section aria-labelledby={`${artemisInstanceId}-calendar-planner-title`} className="art:w-full art:bg-background art:px-3 art:py-6 art:@min-[640px]/artemis:px-6">
      <div className="art:mx-auto art:w-full art:max-w-[1500px]">
        <header className="art:flex art:flex-col art:gap-5 art:pb-5 art:@min-[1024px]/artemis:flex-row art:@min-[1024px]/artemis:items-end art:@min-[1024px]/artemis:justify-between">
          <div>
            <p className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.16em]">Workspace</p>
            <h2 id={`${artemisInstanceId}-calendar-planner-title`} className="art:mt-1 art:text-foreground art:tracking-tight art:text-xl art:font-medium">
              Calendar
            </h2>
            <p className="art:mt-1 art:text-muted-foreground art:text-sm">Plan meetings, focus time, and deadlines in one view.</p>
          </div>
          <div className="art:flex art:flex-col art:gap-2 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-center">
            <PlannerField className="art:flex-1 art:min-w-0 art:@min-[640px]/artemis:w-64" icon={<Search className="art:size-4"/>} type="search" aria-label="Search calendar events" placeholder="Search events" inputClassName="art:pl-10 art:pr-3.5 art:text-base art:placeholder:text-muted-foreground art:@min-[640px]/artemis:text-sm" value={query} onChange={(e) => setQuery(e.target.value)}/>
            <ArtemisButton variant="primary" size="none" className="art:px-4 art:h-9" onClick={() => openAdd(selected)}>
              <Plus className="art:size-4"/>
              Add event
            </ArtemisButton>
          </div>
        </header>
        <div className="art:mb-4 art:overflow-x-auto art:pb-px">
          <div>
            <div role="tablist" className="art:inline-flex art:items-center art:gap-1 art:border-b art:border-border art:min-w-max">
              {CATEGORY_TABS.map((tab) => {
            const active = tab.value === category;
            return (<button key={tab.value} type="button" role="tab" aria-selected={active} className={`art:relative art:isolate art:-mb-px art:inline-flex art:min-h-11 art:items-center art:px-3 art:pt-1 art:pb-2.5 art:font-medium art:text-sm art:transition-colors ${active ? "art:text-foreground" : "art:text-muted-foreground art:hover:text-foreground"}`} onClick={() => setCategory(tab.value)}>
                    {tab.label}

                    {active ? (<motion.span layout="position" layoutId={underlineId} className="art:absolute art:right-0 art:-bottom-px art:left-0 art:h-px art:bg-primary" transition={reduce ? { duration: 0 } : PLANNER_INDICATOR_SPRING}/>) : null}
                  </button>);
        })}
            </div>
          </div>
        </div>
        <div className="art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background">
          <div className="art:flex art:flex-col art:gap-4 art:border-border art:border-b art:p-4 art:@min-[1024px]/artemis:flex-row art:@min-[1024px]/artemis:items-center art:@min-[1024px]/artemis:justify-between">
            <div className="art:flex art:min-w-0 art:items-center art:gap-3">
              <div className="art:grid art:size-11 art:shrink-0 art:place-items-center art:rounded-xl art:border art:border-border art:bg-muted/35">
                <span className="art:font-mono art:text-xs art:text-muted-foreground art:uppercase">{MONTHS_SHORT[anchor.m]}</span>
                <span className="art:-mt-1 art:font-semibold art:text-sm">{anchor.d}</span>
              </div>
              <div className="art:min-w-0">
                <h3 className="art:truncate art:tracking-tight art:text-xl art:font-medium">{view === "month" ? monthTitle(anchor) : weekTitle(anchor)}</h3>
                <p className="art:mt-0.5 art:text-muted-foreground art:text-xs">{visible.length} visible events</p>
              </div>
            </div>
            <div className="art:flex art:flex-wrap art:items-center art:gap-2">
              <div className="art:flex art:items-center art:rounded-full art:border art:border-border art:p-0.5">
                <ArtemisButton variant="ghost" size="icon" className={NAV_BUTTON} aria-label={`Previous ${unit}`} onClick={() => step(-1)}>
                  <ChevronLeft className="art:size-4"/>
                </ArtemisButton>
                <ArtemisButton variant="link" size="none" className={TODAY_BUTTON} aria-label={`Go to today. Viewing ${periodLabel}`} onClick={() => goTo(parseDay(today))}>
                  {periodLabel}
                </ArtemisButton>
                <ArtemisButton variant="ghost" size="icon" className={NAV_BUTTON} aria-label={`Next ${unit}`} onClick={() => step(1)}>
                  <ChevronRight className="art:size-4"/>
                </ArtemisButton>
              </div>
              <div>
                <PlannerSegmentedTabs items={VIEW_TABS} value={view} onValueChange={setView} buttonClassName="art:rounded-full art:h-8 art:py-0 art:text-xs"/>
              </div>
            </div>
          </div>
          <div className="art:overflow-x-auto">
            {view === "month" ? (<MonthView anchor={anchor} direction={direction} today={today} eventsByDate={eventsByDate} onOpenEvent={openEvent} onAddOnDay={openAdd} onShowDay={showDay}/>) : (<WeekView anchor={anchor} direction={direction} today={today} eventsByDate={eventsByDate} onOpenEvent={openEvent}/>)}
          </div>
        </div>
      </div>
      <EventDetailsDialog event={detailsEvent} open={detailsOpen} confirming={confirming} onConfirmingChange={setConfirming} onClose={() => setDetailsOpen(false)} onDelete={deleteEvent}/>
      <AddEventDialog open={addOpen} defaultDate={addDate} formKey={addKey} onClose={() => setAddOpen(false)} onCreate={createEvent}/>
    </section>);
}

