export const MONTHS_LONG = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
] as const;
export const MONTHS_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"] as const;
export const WEEKDAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"] as const;
export type Day = {
    y: number;
    m: number;
    d: number;
};
export function parseDay(key: string): Day {
    const [y, m, d] = key.split("-").map(Number);
    return { y, m: m - 1, d };
}
export function dayKey(day: Day): string {
    return `${day.y}-${String(day.m + 1).padStart(2, "0")}-${String(day.d).padStart(2, "0")}`;
}
export function makeDay(y: number, m: number, d: number): Day {
    const date = new Date(y, m, d);
    return { y: date.getFullYear(), m: date.getMonth(), d: date.getDate() };
}
export function addDays(day: Day, n: number): Day {
    return makeDay(day.y, day.m, day.d + n);
}
export function weekdayIndex(day: Day): number {
    return (new Date(day.y, day.m, day.d).getDay() + 6) % 7;
}
export function startOfWeek(day: Day): Day {
    return addDays(day, -weekdayIndex(day));
}
export function todayKey(): string {
    const now = new Date();
    return dayKey({ y: now.getFullYear(), m: now.getMonth(), d: now.getDate() });
}
export function monthGrid(day: Day): Day[] {
    const first = startOfWeek({ y: day.y, m: day.m, d: 1 });
    return Array.from({ length: 42 }, (_, i) => addDays(first, i));
}
export function weekDays(day: Day): Day[] {
    const first = startOfWeek(day);
    return Array.from({ length: 7 }, (_, i) => addDays(first, i));
}
export function periodKey(view: PlannerView, day: Day): string {
    return view === "month" ? dayKey({ y: day.y, m: day.m, d: 1 }) : dayKey(startOfWeek(day));
}
export function longDate(day: Day): string {
    return `${MONTHS_LONG[day.m]} ${day.d}, ${day.y}`;
}
export function monthTitle(day: Day): string {
    return `${MONTHS_LONG[day.m]} ${day.y}`;
}
export function monthLabel(day: Day): string {
    return `${MONTHS_SHORT[day.m]} ${day.y}`;
}
export function weekTitle(day: Day): string {
    const days = weekDays(day);
    const a = days[0];
    const b = days[6];
    if (a.y !== b.y)
        return `${MONTHS_SHORT[a.m]} ${a.d}, ${a.y} \u2013 ${MONTHS_SHORT[b.m]} ${b.d}, ${b.y}`;
    if (a.m !== b.m)
        return `${MONTHS_SHORT[a.m]} ${a.d} \u2013 ${MONTHS_SHORT[b.m]} ${b.d}, ${b.y}`;
    return `${MONTHS_SHORT[a.m]} ${a.d}\u2013${b.d}, ${b.y}`;
}
export function weekLabel(day: Day): string {
    const days = weekDays(day);
    const a = days[0];
    const b = days[6];
    if (a.m !== b.m)
        return `${MONTHS_SHORT[a.m]} ${a.d}\u2013${MONTHS_SHORT[b.m]} ${b.d}`;
    return `${MONTHS_SHORT[a.m]} ${a.d}\u2013${b.d}`;
}
export function minutesOf(time: string): number {
    const [h, m] = time.split(":").map(Number);
    return h * 60 + m;
}
export function formatTime(time: string): string {
    const [h, m] = time.split(":").map(Number);
    const suffix = h >= 12 ? "PM" : "AM";
    const hour = h % 12 === 0 ? 12 : h % 12;
    return `${hour}:${String(m).padStart(2, "0")} ${suffix}`;
}
export function matchesQuery(event: PlannerEvent, query: string): boolean {
    if (!query)
        return true;
    return event.title.toLowerCase().includes(query) || (event.location ?? "").toLowerCase().includes(query);
}

