}
export type NewEventInput = {
    title: string;
    date: string;
    start: string;
    end: string;
};
const DEFAULT_START = "09:00";
const DEFAULT_END = "10:00";
const PICKER_INPUT = "art:placeholder:text-muted-foreground/60 art:px-3 art:text-sm";
function AddEventForm({ defaultDate, onClose, onCreate }: {
    defaultDate: string;
    onClose: () => void;
    onCreate: (input: NewEventInput) => void;
}) {
    const [title, setTitle] = useState("");
